//
//  Achievements.swift
//  BibleWish
//
//  Badges from biblewish.com (data generated by tools/build_badges.py) that can be worked out on the
//  device. They celebrate faithfulness and are never ranked.
//

import Foundation

struct BadgeDefinition: Codable, Identifiable, Hashable {
    let id: String
    let group: String
    let icon: String
    let name: String
    let description: String
    let metric: String
    let target: Int
}

struct ChapterRef: Hashable {
    let book: Int
    let chapter: Int
}

/// Everything the badge metrics are worked out from.
struct AchievementInput {
    var completed: Set<ChapterRef> = []
    var chaptersPerBook: [Int] = []
    /// When chapters were marked read (reading log), for seasonal badges.
    var log: [BibleViewModel.ReadingLogEntry] = []
    /// Every date something was read: the log plus plan check-offs.
    var readDates: [Date] = []
    var completedPlans = 0
    var favorites = 0
    var notes = 0
    var marginNotes = 0
    var highlights = 0
}

enum AchievementMetrics {

    /// Canonical book ids in Bible order; the position is the book index used in the data files.
    static let bookIds = [
        "GEN", "EXO", "LEV", "NUM", "DEU", "JOS", "JDG", "RUT", "1SA", "2SA", "1KI", "2KI", "1CH",
        "2CH", "EZR", "NEH", "EST", "JOB", "PSA", "PRO", "ECC", "SNG", "ISA", "JER", "LAM", "EZK",
        "DAN", "HOS", "JOL", "AMO", "OBA", "JON", "MIC", "NAM", "HAB", "ZEP", "HAG", "ZEC", "MAL",
        "MAT", "MRK", "LUK", "JHN", "ACT", "ROM", "1CO", "2CO", "GAL", "EPH", "PHP", "COL", "1TH",
        "2TH", "1TI", "2TI", "TIT", "PHM", "HEB", "JAS", "1PE", "2PE", "1JN", "2JN", "3JN", "JUD",
        "REV",
    ]

    /// Chapters read in a span of books: metric → first and last book index.
    private static let bookRanges: [String: ClosedRange<Int>] = [
        "gospels": 39...42, "law": 0...4, "psalms": 18...18, "proverbs": 19...19,
        "paul": 44...56, "nt": 39...65, "ot": 0...38,
    ]

    /// The 10 sections of the Bible, for "Explorer".
    private static let sections: [ClosedRange<Int>] = [
        0...4, 5...16, 17...21, 22...26, 27...38, 39...42, 43...43, 44...56, 57...64, 65...65,
    ]

    private static let christmasChapters: Set<ChapterRef> = [
        ChapterRef(book: 41, chapter: 2), ChapterRef(book: 39, chapter: 1), ChapterRef(book: 39, chapter: 2),
    ]

    private static let easterChapters: Set<ChapterRef> = [
        ChapterRef(book: 39, chapter: 28), ChapterRef(book: 40, chapter: 16), ChapterRef(book: 41, chapter: 24),
        ChapterRef(book: 42, chapter: 20), ChapterRef(book: 45, chapter: 15),
    ]

    /// Turns the saved chapter keys into chapter references, whatever the translation's book names
    /// were when they were saved. The app saves "kjv|John-3" (translation, book, chapter); a key
    /// without the "kjv|" part is accepted too.
    static func chapterRefs(fromKeys keys: Set<String>) -> Set<ChapterRef> {
        var refs: Set<ChapterRef> = []
        for key in keys {
            let bookAndChapter = key.split(separator: "|", maxSplits: 1).last.map(String.init) ?? key
            guard let dash = bookAndChapter.lastIndex(of: "-"),
                  let chapter = Int(bookAndChapter[bookAndChapter.index(after: dash)...]),
                  let id = BookNameMapper.bookId(for: String(bookAndChapter[..<dash])),
                  let book = bookIds.firstIndex(of: id) else { continue }
            refs.insert(ChapterRef(book: book, chapter: chapter))
        }
        return refs
    }

    static func values(for input: AchievementInput) -> [String: Int] {
        var values: [String: Int] = [:]
        let calendar = Calendar.current

        values["chapters"] = input.completed.count
        for (metric, range) in bookRanges {
            values[metric] = input.completed.filter { range.contains($0.book) }.count
        }

        let readBooks = Set(input.completed.map(\.book))
        values["sections"] = sections.filter { section in readBooks.contains { section.contains($0) } }.count
        values["books"] = input.chaptersPerBook.indices.filter { book in
            let total = input.chaptersPerBook[book]
            return total > 0 && input.completed.filter { $0.book == book }.count >= total
        }.count

        let days = Set(input.readDates.map { calendar.startOfDay(for: $0) })
        values["streak"] = longestStreak(of: days, calendar: calendar)
        values["morning"] = Set(input.readDates.filter { calendar.component(.hour, from: $0) < 7 }.map { calendar.startOfDay(for: $0) }).count
        values["evening"] = Set(input.readDates.filter { calendar.component(.hour, from: $0) >= 21 }.map { calendar.startOfDay(for: $0) }).count

        values["plans"] = input.completedPlans
        values["favorites"] = input.favorites
        values["notes"] = input.notes
        values["margin_notes"] = input.marginNotes
        values["highlights"] = input.highlights

        values["season_christmas"] = input.log.contains {
            christmasChapters.contains(ChapterRef(book: $0.bookIndex, chapter: $0.chapter)) && isChristmasSeason($0.date, calendar)
        } ? 1 : 0
        values["season_easter"] = input.log.contains {
            easterChapters.contains(ChapterRef(book: $0.bookIndex, chapter: $0.chapter)) && isEasterWeek($0.date, calendar)
        } ? 1 : 0

        return values
    }

    // MARK: - Dates

    static func longestStreak(of days: Set<Date>, calendar: Calendar) -> Int {
        var longest = 0
        for day in days {
            // Only count from the first day of a run.
            if let before = calendar.date(byAdding: .day, value: -1, to: day), days.contains(before) { continue }
            var length = 1
            var cursor = day
            while let next = calendar.date(byAdding: .day, value: 1, to: cursor), days.contains(next) {
                length += 1
                cursor = next
            }
            longest = max(longest, length)
        }
        return longest
    }

    /// December 20 to 26.
    static func isChristmasSeason(_ date: Date, _ calendar: Calendar) -> Bool {
        let parts = calendar.dateComponents([.month, .day], from: date)
        return parts.month == 12 && (20...26).contains(parts.day ?? 0)
    }

    /// Palm Sunday to the Sunday after Easter.
    static func isEasterWeek(_ date: Date, _ calendar: Calendar) -> Bool {
        let year = calendar.component(.year, from: date)
        guard let easter = easterSunday(year: year, calendar: calendar),
              let start = calendar.date(byAdding: .day, value: -7, to: easter),
              let end = calendar.date(byAdding: .day, value: 7, to: easter) else { return false }
        let day = calendar.startOfDay(for: date)
        return day >= start && day <= end
    }

    /// Western Easter Sunday (the anonymous Gregorian algorithm).
    static func easterSunday(year: Int, calendar: Calendar) -> Date? {
        let a = year % 19
        let b = year / 100
        let c = year % 100
        let d = b / 4
        let e = b % 4
        let f = (b + 8) / 25
        let g = (b - f + 1) / 3
        let h = (19 * a + b - d - g + 15) % 30
        let i = c / 4
        let k = c % 4
        let l = (32 + 2 * e + 2 * i - h - k) % 7
        let m = (a + 11 * h + 22 * l) / 451
        let month = (h + l - 7 * m + 114) / 31
        let day = (h + l - 7 * m + 114) % 31 + 1
        return calendar.date(from: DateComponents(year: year, month: month, day: day))
    }
}

final class AchievementsStore: ObservableObject {

    let badges: [BadgeDefinition]

    /// Badge id → when it was earned. Kept even if progress is later reset.
    @Published private(set) var earned: [String: Date]
    @Published private(set) var values: [String: Int] = [:]
    /// A badge just unlocked, shown briefly by the app.
    @Published private(set) var toast: BadgeDefinition?

    private var toastQueue: [BadgeDefinition] = []
    private let earnedKey = "achievements_earned_v1"
    private let seededKey = "achievements_seeded_v1"

    init() {
        var badges: [BadgeDefinition] = []
        if let url = Bundle.main.url(forResource: "badges", withExtension: "json"),
           let data = try? Data(contentsOf: url),
           let decoded = try? JSONDecoder().decode([BadgeDefinition].self, from: data) {
            badges = decoded
        } else {
            assertionFailure("badges.json is missing or unreadable")
        }
        self.badges = badges

        if let data = UserDefaults.standard.data(forKey: earnedKey),
           let decoded = try? JSONDecoder().decode([String: Date].self, from: data) {
            earned = decoded
        } else {
            earned = [:]
        }
    }

    var groups: [String] {
        var seen: [String] = []
        for badge in badges where !seen.contains(badge.group) { seen.append(badge.group) }
        return seen
    }

    func current(_ badge: BadgeDefinition) -> Int {
        min(values[badge.metric] ?? 0, badge.target)
    }

    func fraction(_ badge: BadgeDefinition) -> Double {
        earned[badge.id] != nil ? 1 : Double(current(badge)) / Double(max(1, badge.target))
    }

    /// The unearned badge that is closest to done.
    var nextBadge: BadgeDefinition? {
        badges.filter { earned[$0.id] == nil && current($0) > 0 }
            .max { fraction($0) < fraction($1) }
    }

    /// Recomputes every badge. Badges already met when the app first looks (progress made before
    /// this version) are awarded quietly; later ones are celebrated.
    func update(with input: AchievementInput) {
        guard input.chaptersPerBook.count == AchievementMetrics.bookIds.count else { return }

        let newValues = AchievementMetrics.values(for: input)
        values = newValues

        let seeded = UserDefaults.standard.bool(forKey: seededKey)
        var newlyEarned: [BadgeDefinition] = []

        for badge in badges where earned[badge.id] == nil && (newValues[badge.metric] ?? 0) >= badge.target {
            earned[badge.id] = Date()
            newlyEarned.append(badge)
        }

        guard !newlyEarned.isEmpty || !seeded else { return }
        if let data = try? JSONEncoder().encode(earned) {
            UserDefaults.standard.set(data, forKey: earnedKey)
        }
        UserDefaults.standard.set(true, forKey: seededKey)

        if seeded {
            toastQueue.append(contentsOf: newlyEarned)
            showNextToast()
        }
    }

    private func showNextToast() {
        guard toast == nil, !toastQueue.isEmpty else { return }
        let badge = toastQueue.removeFirst()
        toast = badge
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 4_000_000_000)
            // Skip if the reader already dismissed it (and a later badge took its place).
            guard toast?.id == badge.id else { return }
            toast = nil
            showNextToast()
        }
    }

    func dismissToast() {
        toast = nil
        showNextToast()
    }
}
